    internal static bool Contains(string[] names, ReadOnlySpan<char> name)
    {
        int minimum = 0;
        int maximum = names.Length - 1;
        while (minimum <= maximum)
        {
            int middle = minimum + (maximum - minimum) / 2;
            int comparison = Compare(name, names[middle]);
            if (comparison == 0)
            {
                return true;
            }

            if (comparison < 0)
            {
                maximum = middle - 1;
            }
            else
            {
                minimum = middle + 1;
            }
        }

        return false;
    }

    internal static int Compare(ReadOnlySpan<char> value, string name)
    {
        int count = value.Length < name.Length ? value.Length : name.Length;
        int index = 0;
        while (index < count)
        {
            char left = Ascii.ToLower(value[index]);
            char right = name[index];
            if (left < right)
            {
                return -1;
            }

            if (left > right)
            {
                return 1;
            }

            index = index + 1;
        }

        if (value.Length < name.Length)
        {
            return -1;
        }

        if (value.Length > name.Length)
        {
            return 1;
        }

        return 0;
    }
